//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_ATTITUDE_TARGET_TYPEMASK(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.ATTITUDE_TARGET_TYPEMASK
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.ATTITUDE_TARGET_TYPEMASK_BODY_ROLL_RATE_IGNORE.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.ATTITUDE_TARGET_TYPEMASK
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.ATTITUDE_TARGET_TYPEMASK_BODY_ROLL_RATE_IGNORE, dec)
	})
}
